{"translations":{"cue-1":"Bạn có tin được không?","cue-2":"Âm thanh nút bấm điều hướng vô cùng cuốn hút của Volvo,","cue-3":"thực chất không hề do các lập trình viên tạo ra.","cue-4":"Các hãng xe khác làm âm thanh nút bấm,","cue-5":"đều ngồi trong văn phòng chỉnh thông số máy tính.","cue-6":"Nhưng các nhà thiết kế của Volvo lại không làm như vậy.","cue-7":"Anh ấy nói,","cue-8":"âm thanh nút bấm này,","cue-9":"chủ xe sẽ phải nghe hàng chục ngàn lần.","cue-10":"Không được chói tai, không được gượng gạo,","cue-11":"càng không được gây bực bội khi nghe lâu.","cue-12":"Cho dù đang kẹt giữa dòng xe cộ tấp nập,","cue-13":"nghe thấy nó cũng khiến lòng người tĩnh lại.","cue-14":"Thế là anh dẫn theo cả đội ngũ,","cue-15":"vào rừng sâu núi thẳm ở lại suốt hai ngày.","cue-16":"Họ bẻ gãy hơn ba trăm cành cây khác nhau,","cue-17":"để thử từng loại gỗ,","cue-18":"cũng như âm thanh khi bẻ gãy ở từng độ dày mỏng.","cue-19":"Hết lần này đến lần khác,","cue-20":"họ đã ghi lại hơn ba trăm loại âm thanh của tự nhiên.","cue-21":"Mục tiêu chỉ có một.","cue-22":"Đó là tìm ra một loại âm thanh","cue-23":"êm ái, tự nhiên, nghe hàng ngàn hàng vạn lần","cue-24":"cũng không thấy bực bội.","cue-25":"Cuối cùng sau vô số lần thử nghiệm,","cue-26":"họ đã tìm thấy.","cue-27":"Giống như khi cành cây nhẹ nhàng gãy gập,","cue-28":"tạo ra một tiếng rắc thật êm ái.","cue-29":"Sau đó họ đã số hóa đoạn âm thanh đến từ rừng sâu này.","cue-30":"Liên tục tinh chỉnh,","cue-31":"gọt giũa,","cue-32":"mới biến thành tiếng click độc đáo trên nút bấm điều hướng của Volvo ngày nay.","cue-33":"Đây cũng là lý do tại sao,","cue-34":"nhiều chủ xe nói rằng nút bấm của Volvo,","cue-35":"là nút bấm chữa lành nhất.","cue-36":"Nghe thấy âm thanh đến từ tự nhiên này,","cue-37":"cho dù bên ngoài có kẹt xe đến đâu,","cue-38":"tâm trạng có bực bội thế nào,","cue-39":"cũng được xoa dịu trong tích tắc.","cue-40":"Hóa ra cảm giác cao cấp,","cue-41":"thực sự được giấu kín,","cue-42":"trong những chi tiết dễ bị bỏ qua nhất.","cue-43":"Bạn còn từng thấy trên xe hơi,","cue-44":"có những thiết kế chi tiết nào ấm áp như thế này nữa không?"}}
[/CANDIDATE_JSON]
